        14 => [1 => 'إِنَّمَا يَسْتَجِيبُ اُ۬لذِينَ يَسْمَعُونَۖ', 2 => 'وَمَا نُرْسِلُ اُ۬لْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۖ', 3 => 'وَعِندَهُۥ مَفَاتِحُ اُ۬لْغَيْبِ لَا يَعْلَمُهَآ إِلَّا هُوَۖ', 4 => 'وَذَرِ اِ۬لذِينَ اَ۪تَّخَذُواْ دِينَهُمْ لَعِباࣰ وَلَهْواࣰ', 5 => 'وَحَآجَّهُۥ قَوْمُهُۥۖ قَالَ أَتُحَٰٓجُّونِے فِے اِ۬للَّهِ', 6 => 'وَمَا قَدَرُواْ اُ۬للَّهَ حَقَّ قَدْرِهِۦ', 7 => 'إِنَّ اَ۬للَّهَ فَٰلِقُ اُ۬لْحَبِّ وَالنَّو۪يٰۖ', 8 => 'لَّا تُدْرِكُهُ اُ۬لَابْصَٰرُۖ وَهُوَ يُدْرِكُ اُ۬لَابْصَٰرَۖ'],
        15 => [1 => 'وَلَوَ اَنَّنَا نَزَّلْنَآ إِلَيْهِمُ اُ۬لْمَلَٰٓئِكَةَ وَكَلَّمَهُمُ اُ۬لْمَوْت۪يٰ', 2 => 'وَذَرُواْ ظَٰهِرَ اَ۬لِاثْمِ وَبَاطِنَهُۥٓۖ', 3 => 'لَهُمْ دَارُ اُ۬لسَّلَٰمِ عِندَ رَبِّهِمْۖ', 4 => 'قُلْ يَٰقَوْمِ اِ۪عْمَلُواْ عَلَيٰ مَكَانَتِكُمُۥٓ إِنِّے عَٰمِلࣱۖ', 5 => 'قَدْ خَسِرَ اَ۬لذِينَ قَتَلُوٓاْ أَوْلَٰدَهُمْ سَفَهاَۢ', 6 => 'قُل لَّآ أَجِدُ فِے مَآ أُوحِيَ إِلَيَّ مُحَرَّماً عَلَيٰ طَاعِمࣲ', 7 => 'قُلْ تَعَالَوَاْ اَتْلُ مَا حَرَّمَ رَبُّكُمْ عَلَيْكُمُۥٓ', 8 => 'هَلْ يَنظُرُونَ إِلَّآ أَن تَاتِيَهُمُ اُ۬لْمَلَٰٓئِكَةُ'],
        16 => [1 => 'اَلَٓمِّٓصَٓۖ كِتَٰبٌ اُنزِلَ إِلَيْكَ', 2 => 'وَقَاسَمَهُمَآ إِنِّے لَكُمَا لَمِنَ اَ۬لنَّٰصِحِينَ', 3 => 'قُلْ مَنْ حَرَّمَ زِينَةَ اَ۬للَّهِ اِ۬لتِےٓ أَخْرَجَ لِعِبَادِهِۦ', 4 => 'وَقَالَتُ ا۟ول۪يٰهُمْ لِأُخْر۪يٰهُمْ', 5 => 'وَإِذَا صُرِفَتَ اَبْصَٰرُهُمْ', 6 => 'وَهُوَ اَ۬لذِے يُرْسِلُ اُ۬لرِّيَٰحَ نُشُراَۢ', 7 => 'أَوَعَجِبْتُمُۥٓ أَن جَآءَكُمْ ذِكْرࣱ مِّن رَّبِّكُمْ', 8 => 'فَعَقَرُواْ اُ۬لنَّاقَةَ وَعَتَوْاْ عَنَ اَمْرِ رَبِّهِمْۖ'],
        17 => [1 => 'قَالَ اَ۬لْمَلَأُ اُ۬لذِينَ اَ۪سْتَكْبَرُواْ', 2 => 'أَوَلَمْ يَهْدِ لِلذِينَ يَرِثُونَ اَ۬لَارْضَ', 3 => 'وَأَوْحَيْنَآ إِلَيٰ مُوس۪يٰٓ أَنَ اَلْقِ عَصَاكَۖ', 4 => 'وَقَالُواْ مَهْمَا تَاتِنَا بِهِۦ مِنَ اٰيَةࣲ', 5 => 'وَوَٰعَدْنَا مُوس۪يٰ ثَلَٰثِينَ لَيْلَةࣰ', 6 => 'وَلَمَّا سُقِطَ فِےٓ أَيْدِيهِمْ', 7 => 'وَاكْتُبْ لَنَا فِے هَٰذِهِ اِ۬لدُّنْي۪ا حَسَنَةࣰ', 8 => 'وَسْـَٔلْهُمْ عَنِ اِ۬لْقَرْيَةِ'],
        18 => [1 => 'وَإِذْ نَتَقْنَا اَ۬لْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةࣱ', 2 => 'وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيراࣰ مِّنَ اَ۬لْجِنِّ وَالِانسِۖ', 3 => 'قُل لَّآ أَمْلِكُ لِنَفْسِے نَفْعاࣰ وَلَا ضَرّاً', 4 => 'خُذِ اِ۬لْعَفْوَۖ وَامُرْ بِالْعُرْفِۖ', 5 => 'كَمَآ أَخْرَجَكَ رَبُّكَ مِنۢ بَيْتِكَ بِالْحَقِّ', 6 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمُ اُ۬لذِينَ كَفَرُواْ', 7 => 'إِنَّ شَرَّ اَ۬لدَّوَآبِّ عِندَ اَ۬للَّهِ اِ۬لصُّمُّ اُ۬لْبُكْمُ', 8 => 'وَإِذَا تُتْل۪يٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا'],
        19 => [1 => 'وَاعْلَمُوٓاْ أَنَّمَا غَنِمْتُم مِّن شَےْءࣲ', 2 => 'وَإِذْ زَيَّنَ لَهُمُ اُ۬لشَّيْطَٰنُ أَعْمَٰلَهُمْ', 3 => 'وَأَعِدُّواْ لَهُم مَّا اَ۪سْتَطَعْتُم مِّن قُوَّةࣲ', 4 => 'وَإِنْ يُّرِيدُواْ خِيَانَتَكَ فَقَدْ خَانُواْ اُ۬للَّهَ', 5 => 'فَإِذَا اَ۪نسَلَخَ اَ۬لَاشْهُرُ اُ۬لْحُرُمُ', 6 => 'وَإِن نَّكَثُوٓاْ أَيْمَٰنَهُم مِّنۢ بَعْدِ عَهْدِهِمْ', 7 => 'أَجَعَلْتُمْ سِقَايَةَ اَ۬لْحَآجِّ وَعِمَارَةَ اَ۬لْمَسْجِدِ', 8 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ إِنَّمَا اَ۬لْمُشْرِكُونَ نَجَسࣱ'],
        20 => [1 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ إِنَّ كَثِيراࣰ مِّنَ اَ۬لَاحْب۪ارِ', 2 => 'اِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ اُ۬للَّهُ', 3 => 'وَلَوَ اَرَادُواْ اُ۬لْخُرُوجَ لَأَعَدُّواْ لَهُۥ عُدَّةࣰۖ', 4 => 'فَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَلَآ أَوْلَٰدُهُمُۥٓۖ', 5 => 'وَمِنْهُمُ اُ۬لذِينَ يُوذُونَ اَ۬لنَّبِےٓءَ', 6 => 'أَلَمْ يَاتِهِمْ نَبَأُ اُ۬لذِينَ مِن قَبْلِهِمْ قَوْمِ نُوحࣲ', 7 => 'وَمِنْهُم مَّنْ عَٰهَدَ اَ۬للَّهَ لَئِنَ اٰت۪يٰنَا مِن فَضْلِهِۦ', 8 => 'وَلَا تُعْجِبْكَ أَمْوَٰلُهُمْ وَأَوْلَٰدُهُمُۥٓۖ'],
        21 => [1 => 'إِنَّمَا اَ۬لسَّبِيلُ عَلَي اَ۬لذِينَ يَسْتَٰذِنُونَكَ', 2 => 'وَمِمَّنْ حَوْلَكُم مِّنَ اَ۬لَاعْرَابِ مُنَٰفِقُونَۖ', 3 => 'اِنَّ اَ۬للَّهَ اَ۪شْتَر۪يٰ مِنَ اَ۬لْمُومِنِينَ أَنفُسَهُمْ', 4 => 'لَّقَد تَّابَ اَ۬للَّهُ عَلَي اَ۬لنَّبِےٓءِ وَالْمُهَٰجِرِينَ', 5 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ قَٰتِلُواْ اُ۬لذِينَ يَلُونَكُم', 6 => 'اِنَّ رَبَّكُمُ اُ۬للَّهُ اُ۬لذِے خَلَقَ اَ۬لسَّمَٰوَٰتِ', 7 => 'وَلَوْ يُعَجِّلُ اُ۬للَّهُ لِلنَّاسِ اِ۬لشَّرَّ', 8 => 'وَمَا كَانَ اَ۬لنَّاسُ إِلَّآ أُمَّةࣰ وَٰحِدَةࣰ'],
        22 => [1 => 'لِّلذِينَ أَحْسَنُواْ اُ۬لْحُسْن۪يٰ وَزِيَادَةࣱۖ', 2 => 'وَمَا كَانَ هَٰذَا اَ۬لْقُرْءَانُ أَنْ يُّفْتَر۪يٰ', 3 => 'قُل لَّآ أَمْلِكُ لِنَفْسِے ضَرّاࣰ وَلَا نَفْعاً', 4 => 'وَمَا تَكُونُ فِے شَأْنࣲ وَمَا تَتْلُواْ مِنْهُ مِن قُرْءَانࣲ', 5 => 'وَاتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ اِذْ قَالَ لِقَوْمِهِۦ يَٰقَوْمِ', 6 => 'فَمَآ ءَامَنَ لِمُوس۪يٰٓ إِلَّا ذُرِّيَّةࣱ مِّن قَوْمِهِۦ', 7 => 'وَلَقَدْ بَوَّأْنَا بَنِےٓ إِسْرَآءِيلَ مُبَوَّأَ صِدْقࣲ', 8 => 'قُلْ يَٰٓأَيُّهَا اَ۬لنَّاسُ إِن كُنتُمْ فِے شَكࣲّ مِّن'],
        23 => [1 => 'وَمَا مِن دَآبَّةࣲ فِے اِ۬لَارْضِ إِلَّا عَلَي اَ۬للَّهِ', 2 => 'مَن كَانَ يُرِيدُ اُ۬لْحَيَوٰةَ اَ۬لدُّنْي۪ا وَزِينَتَهَا', 3 => 'مَثَلُ اُ۬لْفَرِيقَيْنِ كَالَاعْم۪يٰ وَالَاصَمِّ', 4 => 'قَالُواْ يَٰنُوحُ قَدْ جَٰدَلْتَنَا فَأَكْثَرْتَ جِدَٰلَنَا', 5 => 'وَقَالَ اَ۪رْكَبُواْ فِيهَا بِسْمِ اِ۬للَّهِ مُجْر۪يٰهَا وَمُرْس۪يٰهَآۖ', 6 => 'قَالُواْ يَٰهُودُ مَا جِئْتَنَا بِبَيِّنَةࣲ', 7 => 'قَالُواْ يَٰصَٰلِحُ قَدْ كُنتَ فِينَا مَرْجُوّاࣰ', 8 => 'قَالُوٓاْ أَتَعْجَبِينَ مِنَ اَمْرِ اِ۬للَّهِۖ'],
        24 => [1 => 'وَإِلَيٰ مَدْيَنَ أَخَاهُمْ شُعَيْباࣰ', 2 => 'وَيَٰقَوْمِ اِ۪عْمَلُواْ عَلَيٰ مَكَانَتِكُمُۥٓ إِنِّے عَٰمِلࣱۖ', 3 => 'يَوْمَ يَاتِۦ لَا تَكَلَّمُ نَفْسٌ اِلَّا بِإِذْنِهِۦۖ', 4 => 'وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ اَ۬لنَّاسَ أُمَّةࣰ وَٰحِدَةࣰۖ', 5 => 'قَالَ قَآئِلࣱ مِّنْهُمْ لَا تَقْتُلُواْ يُوسُفَ', 6 => 'وَرَٰوَدَتْهُ اُ۬لتِے هُوَ فِے بَيْتِهَا', 7 => 'قَالَ رَبِّ اِ۬لسِّجْنُ أَحَبُّ إِلَيَّ', 8 => 'وَقَالَ لِلذِے ظَنَّ أَنَّهُۥ نَاجࣲ مِّنْهُمَا'],
        25 => [1 => 'وَمَآ أُبَرِّۓُ نَفْسِيَۖ إِنَّ اَ۬لنَّفْسَ لَأَمَّارَةُۢ بِالسُّوٓءِ', 2 => 'قَالَ لَنُ ا۟رْسِلَهُۥ مَعَكُمْ', 3 => 'قَالُوٓاْ إِنْ يَّسْرِقْ فَقَدْ سَرَقَ أَخࣱ لَّهُۥ مِن قَبْلُۖ', 4 => 'فَلَمَّا دَخَلُواْ عَلَيْهِ قَالُواْ يَٰٓأَيُّهَا اَ۬لْعَزِيزُ', 5 => 'رَبِّ قَدَ اٰتَيْتَنِے مِنَ اَ۬لْمُلْكِ', 6 => 'لَقَدْ كَانَ فِے قَصَصِهِمْ عِبْرَةࣱ لِّأُوْلِے اِ۬لَالْبَٰبِۖ', 7 => 'وَإِن تَعْجَبْ فَعَجَبࣱ قَوْلُهُمُۥٓ', 8 => 'لَهُۥ دَعْوَةُ اُ۬لْحَقِّۖ وَالذِينَ يَدْعُونَ مِن دُونِهِۦ'],
        26 => [1 => 'أَفَمَنْ يَّعْلَمُ أَنَّمَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ', 2 => 'كَذَٰلِكَ أَرْسَلْنَٰكَ فِےٓ أُمَّةࣲ قَدْ خَلَتْ مِن قَبْلِهَآ', 3 => 'مَّثَلُ اُ۬لْجَنَّةِ اِ۬لتِے وُعِدَ اَ۬لْمُتَّقُونَ', 4 => 'أَلَٓر۪ۖ كِتَٰبٌ اَنزَلْنَٰهُ إِلَيْكَ لِتُخْرِجَ اَ۬لنَّاسَ', 5 => 'قَالَتْ رُسُلُهُمُۥٓ أَفِے اِ۬للَّهِ شَكࣱّ', 6 => 'اَوَلَمْ يَرَوَاْ اَنَّ اَ۬للَّهَ اَ۬لذِے خَلَقَ اَ۬لسَّمَٰوَٰتِ', 7 => 'اَ۬لَمْ تَرَ إِلَي اَ۬لذِينَ بَدَّلُواْ نِعْمَتَ اَ۬للَّهِ', 8 => 'اِ۬لْحَمْدُ لِلهِ اِ۬لذِے وَهَبَ لِے عَلَي اَ۬لْكِبَرِ'],
        27 => [1 => 'أَلَٓر۪ۖ تِلْكَ ءَايَٰتُ اُ۬لْكِتَٰبِ وَقُرْءَانࣲ مُّبِينࣲۖ', 2 => 'وَأَرْسَلْنَا اَ۬لرِّيَٰحَ لَوَٰقِحَ فَأَنزَلْنَا مِنَ اَ۬لسَّمَآءِ', 3 => 'نَبِّۓْ عِبَادِيَ أَنِّيَ أَنَا اَ۬لْغَفُورُ اُ۬لرَّحِيمُ', 4 => 'وَإِن كَانَ أَصْحَٰبُ اُ۬لَايْكَةِ لَظَٰلِمِينَۖ', 5 => 'أَت۪يٰٓ أَمْرُ اُ۬للَّهِ فَلَا تَسْتَعْجِلُوهُۖ', 6 => 'وَأَلْق۪يٰ فِے اِ۬لَارْضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمْ', 7 => 'وَقِيلَ لِلذِينَ اَ۪تَّقَوْاْ مَاذَآ أَنزَلَ رَبُّكُمْ', 8 => 'وَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ'],
        28 => [1 => 'وَقَالَ اَ۬للَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيْنِ اِ۪ثْنَيْنِۖ', 2 => 'تَاللَّهِ لَقَدَ اَرْسَلْنَآ إِلَيٰٓ أُمَمࣲ مِّن قَبْلِكَ', 3 => 'وَاللَّهُ فَضَّلَ بَعْضَكُمْ عَلَيٰ بَعْضࣲ فِے اِ۬لرِّزْقِۖ', 4 => 'أَلَمْ يَرَوِاْ اِلَي اَ۬لطَّيْرِ مُسَخَّرَٰتࣲ', 5 => 'إِنَّ اَ۬للَّهَ يَامُرُ بِالْعَدْلِ وَالِاحْسَٰنِ', 6 => 'فَإِذَا قَرَأْتَ اَ۬لْقُرْءَانَ فَاسْتَعِذْ بِاللَّهِ', 7 => 'يَوْمَ تَاتِے كُلُّ نَفْسࣲ تُجَٰدِلُ عَن نَّفْسِهَا', 8 => 'اِنَّ إِبْرَٰهِيمَ كَانَ أُمَّةࣰ قَانِتاࣰ لِّلهِ'],
        29 => [1 => 'سُبْحَٰنَ اَ۬لذِےٓ أَسْر۪يٰ بِعَبْدِهِۦ لَيْلاࣰ', 2 => 'وَيَدْعُ اُ۬لِانسَٰنُ بِالشَّرِّ دُعَآءَهُۥ بِالْخَيْرِۖ', 3 => 'وَقَض۪يٰ رَبُّكَ أَلَّا تَعْبُدُوٓاْ إِلَّآ إِيَّاهُۖ', 4 => 'وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌۖ', 5 => 'قُلْ كُونُواْ حِجَارَةً اَوْ حَدِيداً', 6 => 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ اِ۟سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْۖ', 7 => 'وَلَقَدْ كَرَّمْنَا بَنِےٓ ءَادَمَ وَحَمَلْنَٰهُمْ فِے اِ۬لْبَرِّ وَالْبَحْرِ', 8 => 'وَيَسْـَٔلُونَكَ عَنِ اِ۬لرُّوحِۖ'],
        30 => [1 => 'اَوَلَمْ يَرَوَاْ اَنَّ اَ۬للَّهَ اَ۬لذِے خَلَقَ اَ۬لسَّمَٰوَٰتِ', 2 => 'اِ۬لْحَمْدُ لِلهِ اِ۬لذِےٓ أَنزَلَ عَلَيٰ عَبْدِهِ اِ۬لْكِتَٰبَ', 3 => 'وَتَرَي اَ۬لشَّمْسَ إِذَا طَلَعَت تَّزَّٰوَرُ عَن', 4 => 'فَلَا تُمَارِ فِيهِمُۥٓ إِلَّا مِرَآءࣰ ظَٰهِراࣰ', 5 => 'اِنَّ اَ۬لذِينَ ءَامَنُواْ وَعَمِلُواْ اُ۬لصَّٰلِحَٰتِ', 6 => 'وَأُحِيطَ بِثُمُرِهِۦ فَأَصْبَحَ يُقَلِّبُ كَفَّيْهِ', 7 => 'وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ اِ۟سْجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْۖ', 8 => 'وَتِلْكَ اَ۬لْقُر۪يٰٓ أَهْلَكْنَٰهُمْ لَمَّا ظَلَمُواْ'],
        31 => [1 => 'قَالَ أَلَمَ اَقُل لَّكَ إِنَّكَ لَن تَسْتَطِيعَ مَعِے', 2 => 'قَالَ أَمَّا مَن ظَلَمَ فَسَوْفَ نُعَذِّبُهُۥ', 3 => 'اَفَحَسِبَ اَ۬لذِينَ كَفَرُوٓاْ أَنْ يَّتَّخِذُواْ', 4 => 'يَٰزَكَرِيَّآءُ اِ۪نَّا نُبَشِّرُكَ بِغُلَٰمٍ اِ۪سْمُهُۥ يَحْي۪', 5 => 'فَحَمَلَتْهُ فَانتَبَذَتْ بِهِۦ مَكَاناࣰ قَصِيّاࣰۖ', 6 => 'وَاذْكُرْ فِے اِ۬لْكِتَٰبِ إِبْرَٰهِيمَ إِنَّهُۥ كَانَ صِدِّيقاࣰ', 7 => 'فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ اَضَاعُواْ اُ۬لصَّلَوٰةَ', 8 => 'قُلْ مَن كَانَ فِے اِ۬لضَّلَٰلَةِ فَلْيَمْدُدْ لَهُ اُ۬لرَّحْمَٰنُ'],
        32 => [1 => 'طَه۪ۖ مَآ أَنزَلْنَا عَلَيْكَ اَ۬لْقُرْءَانَ لِتَشْق۪يٰٓ', 2 => 'قَالَ قَدُ ا۟وتِيتَ سُؤْلَكَ يَٰمُوس۪يٰۖ', 3 => 'مِنْهَا خَلَقْنَٰكُمْ وَفِيهَا نُعِيدُكُمْ وَمِنْهَا نُخْرِجُكُمْ', 4 => 'قَالُواْ لَن نُّوثِرَكَ عَلَيٰ مَا جَآءَنَا مِنَ اَ۬لْبَيِّنَٰتِ', 5 => 'وَمَآ أَعْجَلَكَ عَن قَوْمِكَ يَٰمُوس۪يٰۖ', 6 => 'قَالَ فَاذْهَبْ فَإِنَّ لَكَ فِے اِ۬لْحَيَوٰةِ أَن تَقُولَ', 7 => 'وَعَنَتِ اِ۬لْوُجُوهُ لِلْحَيِّ اِ۬لْقَيُّومِۖ', 8 => 'قَالَ كَذَٰلِكَ أَتَتْكَ ءَايَٰتُنَا فَنَسِيتَهَاۖ'],
        33 => [1 => 'اَ۪قْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِے غَفْلَةࣲ', 2 => 'فَمَا زَالَت تِّلْكَ دَعْو۪يٰهُمْ حَتَّيٰ جَعَلْنَٰهُمْ', 3 => 'أَوَلَمْ يَرَ اَ۬لذِينَ كَفَرُوٓاْ أَنَّ اَ۬لسَّمَٰوَٰتِ وَالَارْضَ', 4 => 'قُلْ مَنْ يَّكْلَؤُكُم بِاليْلِ وَالنَّه۪ارِ مِنَ اَ۬لرَّحْمَٰنِۖ', 5 => 'وَلَقَدَ اٰتَيْنَآ إِبْرَٰهِيمَ رُشْدَهُۥ مِن قَبْلُ', 6 => 'وَجَعَلْنَٰهُمُۥٓ أَئِمَّةࣰ يَهْدُونَ بِأَمْرِنَاۖ', 7 => 'وَذَا اَ۬لنُّونِ إِذ ذَّهَبَ مُغَٰضِباࣰ', 8 => 'إِنَّ اَ۬لذِينَ سَبَقَتْ لَهُم مِّنَّا اَ۬لْحُسْن۪يٰٓ'],
        34 => [1 => 'يَٰٓأَيُّهَا اَ۬لنَّاسُ اُ۪تَّقُواْ رَبَّكُمُۥٓۖ إِنَّ زَلْزَلَةَ اَ۬لسَّاعَةِ', 2 => 'وَمِنَ اَ۬لنَّاسِ مَنْ يَّعْبُدُ اُ۬للَّهَ عَلَيٰ حَرْفࣲ', 3 => 'هَٰذَٰنِ خَصْمَٰنِ اِ۪خْتَصَمُواْ فِے رَبِّهِمْۖ', 4 => 'ذَٰلِكَۖ وَمَنْ يُّعَظِّمْ حُرُمَٰتِ اِ۬للَّهِ', 5 => 'إِنَّ اَ۬للَّهَ يُدَٰفِعُ عَنِ اِ۬لذِينَ ءَامَنُوٓاْۖ', 6 => 'قُلْ يَٰٓأَيُّهَا اَ۬لنَّاسُ إِنَّمَآ أَنَا لَكُمْ نَذِيرࣱ مُّبِينࣱۖ', 7 => 'ذَٰلِكَۖ وَمَنْ عَاقَبَ بِمِثْلِ مَا عُوقِبَ بِهِۦ', 8 => 'وَإِذَا تُتْل۪يٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا بَيِّنَٰتࣲ تَعْرِفُ فِے وُجُوهِ'],
        35 => [1 => 'قَدَ اَفْلَحَ اَ۬لْمُومِنُونَۖ', 2 => 'فَقَالَ اَ۬لْمَلَأُ اُ۬لذِينَ كَفَرُواْ مِن قَوْمِهِۦ', 3 => 'قَالَ رَبِّ اِ۟نصُرْنِے بِمَا كَذَّبُونِۖ', 4 => 'إِنَّ اَ۬لذِينَ هُم مِّنْ خَشْيَةِ رَبِّهِم مُّشْفِقُونَ', 5 => 'وَلَوْ رَحِمْنَٰهُمْ وَكَشَفْنَا مَا بِهِم مِّن ضُرࣲّ', 6 => 'قُل رَّبِّ إِمَّا تُرِيَنِّے مَا يُوعَدُونَ', 7 => 'أَفَحَسِبْتُمُۥٓ أَنَّمَا خَلَقْنَٰكُمْ عَبَثاࣰ', 8 => 'اِنَّ اَ۬لذِينَ جَآءُو بِالِافْكِ عُصْبَةࣱ مِّنكُمْ'],
        36 => [1 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ لَا تَتَّبِعُواْ', 2 => 'قُل لِّلْمُومِنِينَ يَغُضُّواْ مِنَ اَبْصٰ۪رِهِمْ', 3 => 'اَ۬للَّهُ نُورُ اُ۬لسَّمَٰوَٰتِ وَالَارْضِۖ', 4 => 'أَلَمْ تَرَ أَنَّ اَ۬للَّهَ يُزْجِے سَحَاباࣰ', 5 => 'وَأَقْسَمُواْ بِاللَّهِ جَهْدَ أَيْمَٰنِهِمْ لَئِنَ اَمَرْتَهُمْ', 6 => 'وَالْقَوَٰعِدُ مِنَ اَ۬لنِّسَآءِ اِ۬لتِے لَا يَرْجُونَ', 7 => 'لَّا تَجْعَلُواْ دُعَآءَ اَ۬لرَّسُولِ بَيْنَكُمْ كَدُعَآءِ بَعْضِكُم', 8 => 'تَبَٰرَكَ اَ۬لذِےٓ إِن شَآءَ جَعَلَ لَكَ خَيْراࣰ مِّن'],
        37 => [1 => 'وَقَالَ اَ۬لذِينَ لَا يَرْجُونَ لِقَآءَنَا', 2 => 'وَلَقَدَ اٰتَيْنَا مُوسَي اَ۬لْكِتَٰبَ وَجَعَلْنَا مَعَهُۥٓ أَخَاهُ', 3 => 'اَلَمْ تَرَ إِلَيٰ رَبِّكَ كَيْفَ مَدَّ اَ۬لظِّلَّۖ', 4 => 'تَبَٰرَكَ اَ۬لذِے جَعَلَ فِے اِ۬لسَّمَآءِ بُرُوجاࣰ', 5 => 'طَسِٓمِّٓۖ تِلْكَ ءَايَٰتُ اُ۬لْكِتَٰبِ اِ۬لْمُبِينِۖ', 6 => 'قَالَ لِمَنْ حَوْلَهُۥٓ أَلَا تَسْتَمِعُونَۖ', 7 => 'قَالُواْ لَا ضَيْرَۖ إِنَّآ إِلَيٰ رَبِّنَا مُنقَلِبُونَۖ', 8 => 'وَالذِےٓ أَطْمَعُ أَنْ يَّغْفِرَ لِے خَطِيَٓٔتِے يَوْمَ'],
        38 => [1 => 'قَالُوٓاْ أَنُومِنُ لَكَ وَاتَّبَعَكَ اَ۬لَارْذَلُونَۖ', 2 => 'أَتُتْرَكُونَ فِے مَا هَٰهُنَآ ءَامِنِينَ', 3 => 'أَوْفُواْ اُ۬لْكَيْلَۖ وَلَا تَكُونُواْ مِنَ اَ۬لْمُخْسِرِينَۖ', 4 => 'وَمَا تَنَزَّلَتْ بِهِ اِ۬لشَّيَٰطِينُ وَمَا يَنۢبَغِے لَهُمْ', 5 => 'وَإِنَّكَ لَتُلَقَّي اَ۬لْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍۖ', 6 => 'وَحُشِرَ لِسُلَيْمَٰنَ جُنُودُهُۥ مِنَ اَ۬لْجِنِّ وَالِانسِ', 7 => 'قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ اَ۬لْكَٰذِبِينَۖ', 8 => 'قَالَ نَكِّرُواْ لَهَا عَرْشَهَا نَنظُرَ اَتَهْتَدِےٓ'],
        39 => [1 => 'فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخْرِجُوٓاْ', 2 => 'بَلِ اِ۪دَّٰرَكَ عِلْمُهُمْ فِے اِ۬لَاخِرَةِۖ', 3 => 'وَإِذَا وَقَعَ اَ۬لْقَوْلُ عَلَيْهِمُۥٓ', 4 => 'طَسِٓمِّٓۖ تِلْكَ ءَايَٰتُ اُ۬لْكِتَٰبِ اِ۬لْمُبِينِۖ نَتْلُواْ', 5 => 'وَحَرَّمْنَا عَلَيْهِ اِ۬لْمَرَاضِعَ مِن قَبْلُ', 6 => 'وَلَمَّا تَوَجَّهَ تِلْقَآءَ مَدْيَنَ', 7 => 'فَلَمَّا قَض۪يٰ مُوسَي اَ۬لَاجَلَ وَسَارَ بِأَهْلِهِۦٓ', 8 => 'وَاسْتَكْبَرَ هُوَ وَجُنُودُهُۥ فِے اِ۬لَارْضِ'],
        40 => [1 => 'وَلَقَدْ وَصَّلْنَا لَهُمُ اُ۬لْقَوْلَ لَعَلَّهُمْ يَتَذَكَّرُونَۖ', 2 => 'قَالَ اَ۬لذِينَ حَقَّ عَلَيْهِمُ اُ۬لْقَوْلُ', 3 => 'إِنَّ قَارُونَ كَانَ مِن قَوْمِ مُوس۪يٰ', 4 => 'تِلْكَ اَ۬لدَّارُ اُ۬لَاخِرَةُ', 5 => 'وَوَصَّيْنَا اَ۬لِانسَٰنَ بِوَٰلِدَيْهِ حُسْناࣰۖ وَإِن', 6 => 'إِنَّمَا تَعْبُدُونَ مِن دُونِ اِ۬للَّهِ أَوْثَٰناࣰ', 7 => 'فَـَٔامَنَ لَهُۥ لُوطࣱۖ', 8 => 'وَإِلَيٰ مَدْيَنَ أَخَاهُمْ شُعَيْباࣰ فَقَالَ يَٰقَوْمِ'],
        41 => [1 => 'وَلَا تُجَٰدِلُوٓاْ أَهْلَ اَ۬لْكِتَٰبِ', 2 => 'وَكَأَيِّن مِّن دَآبَّةࣲ لَّا تَحْمِلُ رِزْقَهَا', 3 => 'اَوَلَمْ يَسِيرُواْ فِے اِ۬لَارْضِ فَيَنظُرُواْ', 4 => 'وَمِنَ اٰيَٰتِهِۦ خَلْقُ اُ۬لسَّمَٰوَٰتِ وَالَارْضِ', 5 => 'فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفاࣰ فِطْرَتَ اَ۬للَّهِ', 6 => 'ظَهَرَ اَ۬لْفَسَادُ فِے اِ۬لْبَرِّ وَالْبَحْرِ', 7 => 'اَ۬للَّهُ اُ۬لذِے خَلَقَكُم مِّن ضُعْفࣲ', 8 => 'وَلَقَدَ اٰتَيْنَا لُقْمَٰنَ اَ۬لْحِكْمَةَ'],
        42 => [1 => 'وَمَنْ يُّسْلِمْ وَجْهَهُۥٓ إِلَي اَ۬للَّهِ وَهُوَ', 2 => 'يَٰٓأَيُّهَا اَ۬لنَّاسُ اُ۪تَّقُواْ رَبَّكُمْ وَاخْشَوْاْ', 3 => 'قُلْ يَتَوَفّ۪يٰكُم مَّلَكُ اُ۬لْمَوْتِ اِ۬لذِے وُكِّلَ', 4 => 'وَلَقَدَ اٰتَيْنَا مُوسَي اَ۬لْكِتَٰبَۖ فَلَا تَكُن فِے مِرْيَةࣲ', 5 => 'اِ۬لنَّبِےٓءُ اَ۬وْل۪يٰ بِالْمُومِنِينَ مِنَ اَنفُسِهِمْۖ', 6 => 'وَإِذْ قَالَت طَّآئِفَةࣱ مِّنْهُمْ يَٰٓأَهْلَ يَثْرِبَ', 7 => 'قَدْ يَعْلَمُ اُ۬للَّهُ اُ۬لْمُعَوِّقِينَ مِنكُمْ', 8 => 'وَرَدَّ اَ۬للَّهُ اُ۬لذِينَ كَفَرُواْ بِغَيْظِهِمْ لَمْ يَنَالُواْ خَيْراࣰۖ'],
        43 => [1 => 'وَمَنْ يَّقْنُتْ مِنكُنَّ لِلهِ وَرَسُولِهِۦ', 2 => 'فَلَمَّا قَض۪يٰ زَيْدࣱ مِّنْهَا وَطَراࣰ زَوَّجْنَٰكَهَا', 3 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ إِذَا نَكَحْتُمُ', 4 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ لَا تَدْخُلُواْ بُيُوتَ اَ۬لنَّبِےٓءِ', 5 => 'لَّئِن لَّمْ يَنتَهِ اِ۬لْمُنَٰفِقُونَ وَالذِينَ فِے قُلُوبِهِم', 6 => 'اِ۬لْحَمْدُ لِلهِ اِ۬لذِے لَهُۥ مَا فِے اِ۬لسَّمَٰوَٰتِ وَمَا فِے', 7 => 'وَلَقَدَ اٰتَيْنَا دَاوُۥدَ مِنَّا فَضْلاࣰ يَٰجِبَالُ أَوِّبِے', 8 => 'وَجَعَلْنَا بَيْنَهُمْ وَبَيْنَ اَ۬لْقُرَي اَ۬لتِے بَٰرَكْنَا فِيهَا'],
        44 => [1 => 'قُلْ مَنْ يَّرْزُقُكُم مِّنَ اَ۬لسَّمَٰوَٰتِ', 2 => 'وَمَآ أَمْوَٰلُكُمْ وَلَآ أَوْلَٰدُكُم بِالتِے تُقَرِّبُكُمْ', 3 => 'قُلِ اِنَّمَآ أَعِظُكُم بِوَٰحِدَةٍۖ', 4 => 'اَفَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ فَر۪ء۪اهُ حَسَناࣰۖ', 5 => 'يَٰٓأَيُّهَا اَ۬لنَّاسُ أَنتُمُ اُ۬لْفُقَرَآءُ اِ۪لَي اَ۬للَّهِۖ', 6 => 'وَالذِےٓ أَوْحَيْنَآ إِلَيْكَ مِنَ اَ۬لْكِتَٰبِ', 7 => 'اِنَّ اَ۬للَّهَ يُمْسِكُ اُ۬لسَّمَٰوَٰتِ وَالَارْضَ أَن', 8 => 'لَقَدْ حَقَّ اَ۬لْقَوْلُ عَلَيٰٓ أَكْثَرِهِمْ فَهُمْ لَا يُومِنُونَۖ'],
        45 => [1 => 'وَمَآ أَنزَلْنَا عَلَيٰ قَوْمِهِۦ مِنۢ بَعْدِهِۦ مِن', 2 => 'وَمَا تَاتِيهِم مِّنَ اٰيَةࣲ مِّنَ اٰيَٰتِ رَبِّهِمُۥٓ', 3 => 'أَلَمَ اَعْهَدِ اِلَيْكُمْ يَٰبَنِےٓ ءَادَمَ', 4 => 'اِ۬لذِے جَعَلَ لَكُم مِّنَ اَ۬لشَّجَرِ اِ۬لَاخْضَرِ نَاراࣰ', 5 => 'اَ۟حْشُرُواْ اُ۬لذِينَ ظَلَمُواْ وَأَزْوَٰجَهُمْ', 6 => 'قَالَ قَآئِلࣱ مِّنْهُمُۥٓ إِنِّے كَانَ لِے قَرِينࣱ', 7 => 'وَإِنَّ مِن شِيعَتِهِۦ لَإِبْرَٰهِيمَ إِذْ جَآءَ رَبَّهُۥ', 8 => 'وَلَقَدْ مَنَنَّا عَلَيٰ مُوس۪يٰ وَهَٰرُونَ'],
        46 => [1 => 'فَنَبَذْنَٰهُ بِالْعَرَآءِ وَهُوَ سَقِيمࣱۖ', 2 => 'صَٓۖ وَالْقُرْءَانِ ذِے اِ۬لذِّكْرِۖ', 3 => 'وَهَلَ اَت۪يٰكَ نَبَؤُاْ اُ۬لْخَصْمِ', 4 => 'اِذْ عُرِضَ عَلَيْهِ بِالْعَشِيِّ اِ۬لصَّٰفِنَٰتُ اُ۬لْجِيَادُ', 5 => 'وَعِندَهُمْ قَٰصِرَٰتُ اُ۬لطَّرْفِ أَتْرَابٌۖ', 6 => 'قَالَ فَالْحَقَّ وَالْحَقَّ أَقُولُۖ', 7 => 'وَإِذَا مَسَّ اَ۬لِانسَٰنَ ضُرࣱّ دَعَا رَبَّهُۥ مُنِيباً اِلَيْهِۖ', 8 => 'أَلَمْ تَرَ أَنَّ اَ۬للَّهَ أَنزَلَ مِنَ اَ۬لسَّمَآءِ مَآءࣰ'],
        47 => [1 => 'فَمَنَ اَظْلَمُ مِمَّن كَذَبَ عَلَي اَ۬للَّهِ وَكَذَّبَ', 2 => 'اِ۬للَّهُ يَتَوَفَّي اَ۬لَانفُسَ حِينَ مَوْتِهَا', 3 => 'وَأَنِيبُوٓاْ إِلَيٰ رَبِّكُمْ وَأَسْلِمُواْ لَهُۥ', 4 => 'وَمَا قَدَرُواْ اُ۬للَّهَ حَقَّ قَدْرِهِۦ', 5 => 'ح۪مِٓۖ تَنزِيلُ اُ۬لْكِتَٰبِ مِنَ اَ۬للَّهِ اِ۬لْعَزِيزِ اِ۬لْعَلِيمِ', 6 => 'قَالُواْ رَبَّنَآ أَمَتَّنَا اَ۪ثْنَتَيْنِ وَأَحْيَيْتَنَا اَ۪ثْنَتَيْنِ', 7 => 'اَوَلَمْ يَسِيرُواْ فِے اِ۬لَارْضِ فَيَنظُرُواْ كَيْفَ كَانَ', 8 => 'وَقَالَ اَ۬لذِےٓ ءَامَنَ يَٰقَوْمِ إِنِّيَ أَخَافُ عَلَيْكُم'],
        48 => [1 => 'وَيَٰقَوْمِ مَا لِيَ أَدْعُوكُمُۥٓ إِلَي اَ۬لنَّجَوٰةِ', 2 => 'وَلَقَدَ اٰتَيْنَا مُوسَي اَ۬لْهُد۪يٰ', 3 => 'قُلِ اِنِّے نُهِيتُ أَنَ اَعْبُدَ', 4 => 'اَ۬للَّهُ اُ۬لذِے جَعَلَ لَكُمُ اُ۬لَانْعَٰمَ لِتَرْكَبُواْ مِنْهَا', 5 => 'قُلَ اَئِنَّكُمْ لَتَكْفُرُونَ بِالذِے خَلَقَ اَ۬لَارْضَ', 6 => 'وَأَمَّا ثَمُودُ فَهَدَيْنَٰهُمْ فَاسْتَحَبُّواْ اُ۬لْعَم۪يٰ', 7 => 'وَقَيَّضْنَا لَهُمْ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيْنَ أَيْدِيهِمْ', 8 => 'فَإِنِ اِ۪سْتَكْبَرُواْ فَالذِينَ عِندَ رَبِّكَ يُسَبِّحُونَ'],
        49 => [1 => 'إِلَيْهِ يُرَدُّ عِلْمُ اُ۬لسَّاعَةِۖ', 2 => 'يَكَادُ اُ۬لسَّمَٰوَٰتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّۖ', 3 => 'شَرَعَ لَكُم مِّنَ اَ۬لدِّينِ مَا وَصّ۪يٰ بِهِۦ نُوحاࣰ', 4 => 'مَن كَانَ يُرِيدُ حَرْثَ اَ۬لَاخِرَةِ', 5 => 'وَلَوْ بَسَطَ اَ۬للَّهُ اُ۬لرِّزْقَ لِعِبَادِهِۦ', 6 => 'اِنَّمَا اَ۬لسَّبِيلُ عَلَي اَ۬لذِينَ يَظْلِمُونَ اَ۬لنَّاسَ', 7 => 'وَمَا كَانَ لِبَشَرٍ اَنْ يُّكَلِّمَهُ اُ۬للَّهُ إِلَّا وَحْياً', 8 => 'وَالذِے نَزَّلَ مِنَ اَ۬لسَّمَآءِ مَآءَۢ بِقَدَرࣲ'],
        50 => [1 => 'قُلَ اَوَلَوْ جِئْتُكُم بِأَهْد۪يٰ مِمَّا وَجَدتُّمْ عَلَيْهِ', 2 => 'فَاسْتَمْسِكْ بِالذِےٓ أُوحِيَ إِلَيْكَۖ', 3 => 'وَلَمَّا جَآءَ عِيس۪يٰ بِالْبَيِّنَٰتِ', 4 => 'وَتَبَٰرَكَ اَ۬لذِے لَهُۥ مُلْكُ اُ۬لسَّمَٰوَٰتِ وَالَارْضِ', 5 => 'كَمْ تَرَكُواْ مِن جَنَّٰتࣲ وَعُيُونࣲ', 6 => 'ح۪مِٓۖ تَنزِيلُ اُ۬لْكِتَٰبِ مِنَ اَ۬للَّهِ اِ۬لْعَزِيزِ اِ۬لْحَكِيمِۖ', 7 => 'قُل لِّلذِينَ ءَامَنُواْ يَغْفِرُواْ', 8 => 'وَإِذَا تُتْل۪يٰ عَلَيْهِمُۥٓ ءَايَٰتُنَا بَيِّنَٰتࣲ'],
        51 => [1 => 'سورة الأحقاف', 2 => 'وَوَصَّيْنَا اَ۬لِانسَٰنَ بِوَٰلِدَيْهِ حُسْناًۖ حَمَلَتْهُ', 3 => 'وَاذْكُرَ اَخَا عَادٍ اِذَ اَنذَرَ قَوْمَهُۥ بِالَاحْقَافِ', 4 => 'اَوَلَمْ يَرَوَاْ اَنَّ اَ۬للَّهَ اَ۬لذِے خَلَقَ اَ۬لسَّمَٰوَٰتِ', 5 => 'أَفَلَمْ يَسِيرُواْ فِے اِ۬لَارْضِ فَيَنظُرُواْ', 6 => 'وَيَقُولُ اُ۬لذِينَ ءَامَنُواْ لَوْلَا نُزِّلَتْ سُورَةࣱۖ', 7 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُوٓاْ أَطِيعُواْ اُ۬للَّهَ وَأَطِيعُواْ', 8 => 'اِنَّآ أَرْسَلْنَٰكَ شَٰهِداࣰ وَمُبَشِّراࣰ وَنَذِيراࣰ'],
        52 => [1 => 'لَّقَدْ رَضِيَ اَ۬للَّهُ عَنِ اِ۬لْمُومِنِينَ إِذْ يُبَايِعُونَكَ', 2 => 'لَّقَدْ صَدَقَ اَ۬للَّهُ رَسُولَهُ اُ۬لرُّءْي۪ا بِالْحَقِّ', 3 => 'يَٰٓأَيُّهَا اَ۬لذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيْنَ يَدَيِ اِ۬للَّهِ', 4 => 'وَإِن طَآئِفَتَٰنِ مِنَ اَ۬لْمُومِنِينَ اَ۪قْتَتَلُواْ', 5 => 'قَالَتِ اِ۬لَاعْرَابُ ءَامَنَّا قُل لَّمْ تُومِنُواْ', 6 => 'وَنَزَّلْنَا مِنَ اَ۬لسَّمَآءِ مَآءࣰ مُّبَٰرَكاࣰ فَأَنۢبَتْنَا بِهِۦ', 7 => 'قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطْغَيْتُهُۥ', 8 => 'سورة الذاريات'],
        53 => [1 => 'قَالَ فَمَا خَطْبُكُمُۥٓ أَيُّهَا اَ۬لْمُرْسَلُونَۖ', 2 => 'وَمَا خَلَقْتُ اُ۬لْجِنَّ وَالِانسَ إِلَّا لِيَعْبُدُونِۖ', 3 => 'وَيَطُوفُ عَلَيْهِمْ غِلْمَانࣱ لَّهُمْ كَأَنَّهُمْ لُؤْلُؤࣱ مَّكْنُونࣱۖ', 4 => 'وَإِنْ يَّرَوْاْ كِسْفاࣰ مِّنَ اَ۬لسَّمَآءِ سَاقِطاࣰ', 5 => 'وَكَم مِّن مَّلَكࣲ فِے اِ۬لسَّمَٰوَٰتِ لَا تُغْنِے', 6 => 'وَأَنَّ عَلَيْهِ اِ۬لنَّشْأَةَ اَ۬لُاخْر۪يٰۖ', 7 => 'فَدَعَا رَبَّهُۥٓ أَنِّے مَغْلُوبࣱ فَانتَصِرْۖ', 8 => 'وَلَقَدْ رَٰوَدُوهُ عَن ضَيْفِهِۦ فَطَمَسْنَآ أَعْيُنَهُمْ'],
